            diags.push(diag::fix(d, "write one byte as `b'\\xHH'`, or the character's bytes as `b\"...\"`", None));
        }
    }
    if q == 34 {
        out.push(Token { tok: Tok::Bytes(bytes), span: s });
    } else {
        if bytes.len() != 1 && !non_ascii && !bad_escape {
            diags.push(diag::new("E0101", s, "a byte literal holds one byte; use `b\"...\"` for several"));
        }
        let mut v: u8 = 0;
        if bytes.len() > 0 {
            v = bytes[0];
        }
        out.push(Token { tok: Tok::Byte(v), span: s });
    }
    i
}

#[effects(alloc)]
fn string_lit(file: u32, text: &str, start: usize, out: &mut Vec<Token>, diags: &mut diag::Diags) -> usize
    requires start < text.len(),
{
    let n: usize = text.len();
    let mut i: usize = start + 1;
    let mut s: String = String::new();
    while i < n && at(text, i, 0) != 34
        invariant i <= n, n == text.len(),
        decreases n - i,
    {
        if at(text, i, 0) == 92 {
            let e: Esc = char_escape(text, i);
            if e.ok {
                push_code(&mut s, e.ch);
            } else {
                diags.push(bad_escape(span(file, i, i.saturating_add(e.n))));
            }
            i = fwd(i, e.n, n);
        } else {
            push_code(&mut s, char_code(text, i));
            i = fwd(i, char_len(text, i), n);
        }
    }
    if i >= n {
        diags.push(diag::new("E0102", span(file, start, i), "unterminated string literal"));
        return n;
    }
    i = i + 1;
    out.push(Token { tok: Tok::Str(s), span: span(file, start, i) });
    i
}

#[effects(alloc)]
fn render(d: &Diag, sm: &source::SourceMap) -> String {
    let a: source::Pos = sm.line_col(d.span.file, d.span.lo);
    let b: source::Pos = sm.line_col(d.span.file, d.span.hi);
    let mut s: String = String::from("{\"code\":");
    std::json::push_string(&mut s, d.code.as_str());
    s.push_str(",\"sev\":\"");
    push_severity(&mut s, d.code.as_str());
    s.push_str("\",\"message\":");
    std::json::push_string(&mut s, d.message.as_str());
    s.push_str(",\"file\":");
    sm.push_name(&mut s, d.span.file);
    s.push_str(",\"line\":");
    std::num::push_u64(&mut s, a.line as u64);
    s.push_str(",\"col\":");
    std::num::push_u64(&mut s, a.col as u64);
    s.push_str(",\"end_line\":");
    std::num::push_u64(&mut s, b.line as u64);
    s.push_str(",\"end_col\":");
    std::num::push_u64(&mut s, b.col as u64);
    match &d.obligation {
        None => {},
        Some(o) => { s.push_str(",\"obligation\":"); std::json::push_string(&mut s, o.as_str()); },
    }
    match &d.bounded {
        None => {},
        Some(k) => { s.push_str(",\"bounded\":{\"b\":"); std::num::push_i64(&mut s, k.b); s.push_str(",\"l\":"); std::num::push_u64(&mut s, k.l as u64); s.push_str("}"); },
    }
    match &d.fix {
        None => {},
        Some(f) => { s.push_str(",\"fix\":{\"message\":"); std::json::push_string(&mut s, f.message.as_str()); match &f.replacement { None => {}, Some(r) => { s.push_str(",\"replacement\":"); std::json::push_string(&mut s, r.as_str()); }, } s.push_str("}"); },
    }
    s.push_str("}");
    s
}

